import json,pathlib,sys,time
source=pathlib.Path(__file__).resolve().parents[1];root=source;sys.path.insert(0,str(source/'tools'))
from device_cdp import Device
(source/'work').mkdir(exist_ok=True);d=Device();results=[]
def check(name,code,predicate=bool):
 try:
  value=d.evaluate(code);passed=bool(predicate(value));results.append({'test':name,'passed':passed,'evidence':value});print('PASS' if passed else 'FAIL',name,flush=True)
 except Exception as error:results.append({'test':name,'passed':False,'error':str(error)});print('FAIL',name,str(error)[:500],flush=True)
try:
 assert d.evaluate("forge.state.project.startsWith('input-check-')")
 check('Incremental LSP changes preserve multiline UTF-16 edits',r'''(async()=>{
  window.featureProbe={};const model=forge.active.model,uri=model.uri.toString();model.setValue('// emoji: 😀\nint main() {\n    int value = 2;\n    return value;\n}\n');await NativeEditing.sync();forge.lsp.sync(model);
  const messages=[],notify=forge.lsp.notify.bind(forge.lsp);forge.lsp.notify=(method,params)=>{if(method==='textDocument/didChange')messages.push(params);return notify(method,params);};
  try{model.pushEditOperations([],[{range:new monaco.Range(1,14,1,14),text:' Привет'},{range:new monaco.Range(4,12,4,17),text:'missing_incremental_probe()'}],()=>null);await NativeEditing.sync();forge.lsp.sync(model);for(let n=0;n<100;n++){if(forge.diagnosticMap.get(uri)?.diagnostics.some(x=>x.message.includes('missing_incremental_probe')))break;await new Promise(r=>setTimeout(r,25));}
   return {changes:messages.flatMap(m=>m.contentChanges),diagnostics:forge.diagnosticMap.get(uri)?.diagnostics,native:(await native('editorSnapshot',{uri}))[0].text===model.getValue()};
  }finally{forge.lsp.notify=notify;}
 })()''',lambda r:r['native'] and all('range'in c for c in r['changes']) and any('missing_incremental_probe'in e['message'] and e['range']['start']['line']==3 for e in r['diagnostics']))
 check('clangd rename updates the actual native buffer',r'''(async()=>{const model=forge.active.model;model.setValue('int main() { int value = 2; return value; }\n');await NativeEditing.sync();const edit=await forge.lsp.request('textDocument/rename',{...forge.lsp.at(model,{lineNumber:1,column:18}),newName:'renamed'});await forge.applyEdit(edit);await NativeEditing.sync();return {text:model.getValue(),native:(await native('editorSnapshot',{uri:model.uri.toString()}))[0].text};})()''',lambda r:r['text']==r['native'] and r['text'].count('renamed')==2 and 'value'not in r['text'])
 check('Formatter respects requested reference, pointer and range-for spacing',r'''(async()=>{const model=forge.active.model;model.setValue('#include <vector>\nint main(){std::vector<int> v{1,2};for(auto & el:v){auto*ptr=&el;*ptr+=1;}}\n');await NativeEditing.sync();await forge.formatCurrentDocument();return {text:model.getValue(),native:(await native('editorSnapshot',{uri:model.uri.toString()}))[0].text};})()''',lambda r:r['text']==r['native'] and 'for (auto& el : v)'in r['text'] and 'auto *ptr'in r['text'])
 check('Native undo restores formatting changes without losing text',r'''(async()=>{await native('editorAction',{id:'primary',action:'undo'});await NativeEditing.sync();return forge.active.model.getValue();})()''',lambda r:'for(auto & el:v)'in r)
 check('Formatter builder saves a real validated profile and preserves YAML comments',r'''(async()=>{await forge.openFormatter();forge.formatterRaw.setValue(forge.formatterConfig.defaults+'\n# preserved-fixture-comment\n');forge.renderFormatterFields();const input=document.querySelector('[data-format-key="IndentWidth"]');input.value='6';input.onchange();const preview=await forge.refreshFormatterPreview(),after=forge.formatterAfter.getValue();await forge.saveFormatter();const saved=(await native('read',{path:forge.state.root+'/.clang-format'})).text;return {preview,after,saved,closed:!document.querySelector('#formatterDialog').open};})()''',lambda r:r['preview'] and r['closed'] and 'IndentWidth: 6'in r['saved'] and '# preserved-fixture-comment'in r['saved'] and '\n      'in r['after'])
 check('CMake completion and documentation use installed CMake',r'''(async()=>{await forge.openFile(forge.state.root+'/CMakeLists.txt');await NativeEditing.sync();const model=forge.active.model;model.setValue('cmake_minimum_required(VERSION 3.22)\nproject(input_fixture LANGUAGES CXX)\nadd_executable(app main.cpp)\n');await NativeEditing.sync();forge.editor.setPosition({lineNumber:1,column:5});await NativeEditing.sync();const items=await nativeBuildCompletions(model,{lineNumber:1,column:5});await NativeEditing.action('editor.action.showHover');const text=document.querySelector('#nativeInfoDialog pre').textContent;document.querySelector('#nativeInfoDialog').close();return {completion:items.some(x=>x.label==='cmake_minimum_required'),help:text.slice(0,250)};})()''',lambda r:r['completion'] and 'cmake_minimum_required'in r['help'])
 check('CMake, warnings, errors and file controls use distinct vector artwork',r'''({cmake:fileSymbol('CMakeLists.txt'),warning:svg('triangle-alert'),error:svg('circle-x'),hydrated:[...document.querySelectorAll('[data-icon]')].every(e=>e.querySelector('svg')),tabCloses:[...document.querySelectorAll('.tab-close')].every(e=>e.querySelector('svg')),treeFiles:[...document.querySelectorAll('.file-icon')].every(e=>e.querySelector('svg'))})''',lambda r:all(r[k] for k in ['hydrated','tabCloses','treeFiles']) and all('<svg'in r[k] for k in ['cmake','warning','error']) and r['cmake']!=r['warning']!=r['error'])
finally:
 try:d.evaluate("(async()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());await forge.openFile(forge.state.root+'/main.cpp');forge.setCodeScale(100);forge.setUIScale(100);await forge.saveAll();})()")
 except Exception:pass
 report={'device':'realme RMX3951','android':'16','results':results,'passed':sum(r['passed'] for r in results),'total':len(results)}
 (source/'verification-native-features.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps({'passed':report['passed'],'total':report['total']}));d.close()
